# Counterexample: USERPROFILE is mutable and must not redefine the machine default.
$ErrorActionPreference='Stop'; $real=(& node -e "console.log(require('node:os').userInfo().homedir)").Trim(); $old=$env:USERPROFILE; try { $env:USERPROFILE='C:\imc-homeguard-foreign-profile'; $again=(& node -e "console.log(require('node:os').userInfo().homedir)").Trim(); if($again -ne $real){throw "os.userInfo().homedir changed under USERPROFILE override: $again"}; $default=Join-Path $real '.imcodes'; if($default -like '*imc-homeguard-foreign-profile*'){throw 'default path followed mutable USERPROFILE'}; Write-Output "windows identity PASS real=$real default=$default" } finally { $env:USERPROFILE=$old }
